#include <vector>
#include <iostream>

int main() {
    std::vector<int> v;
    // Capacity value is ID and might change based on compiler/library
    std::cout << "Max Size: " << v.max_size() << "\n";

    v.reserve(1); 
    size_t c1 = v.capacity();
    v.push_back(1);
    v.push_back(2); // Triggers reallocation (if c1 == 1)
    size_t c2 = v.capacity();

    std::cout << "Initial Capacity: " << c1 << "\n";
    std::cout << "New Capacity: " << c2 << " (Growth factor used: " << (double)c2/c1 << ")\n";
}
